worked.setupSql:
CREATE TEMP TABLE lesson_orders (
  order_id BIGINT PRIMARY KEY,
  state TEXT NOT NULL CHECK (state IN ('draft','confirmed','cancelled')),
  created_at TIMESTAMPTZ NOT NULL
);
CREATE TEMP TABLE lesson_order_items (
  order_item_id BIGINT PRIMARY KEY,
  order_id BIGINT NOT NULL REFERENCES pg_temp.lesson_orders(order_id),
  sku TEXT NOT NULL,
  quantity INTEGER NOT NULL CHECK (quantity > 0),
  unit_price NUMERIC(12,2) NOT NULL CHECK (unit_price >= 0)
);
CREATE TEMP TABLE lesson_payments (
  payment_id BIGINT PRIMARY KEY,
  order_id BIGINT NOT NULL REFERENCES pg_temp.lesson_orders(order_id),
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  status TEXT NOT NULL CHECK (status IN ('succeeded','pending','failed')),
  paid_at TIMESTAMPTZ NULL
);
CREATE TEMP TABLE lesson_refunds (
  refund_id BIGINT PRIMARY KEY,
  payment_id BIGINT NOT NULL REFERENCES pg_temp.lesson_payments(payment_id),
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  status TEXT NOT NULL CHECK (status IN ('succeeded','pending','failed'))
);
